import {humanComment} from './human-coach.js';
import {getLanguage} from './i18n.js';
import {localComment,localAnswer} from './coach-localized.js';
import {Chess} from './vendor/chess.js';
import {names,values,opposite,moveEvidence,hanging,pins} from './tactics.js';
const piece=p=>names[p.type];
const target=p=>(p.type==='q'||p.type==='r'?'la ':'il ')+piece(p);
export function briefComment(move,before,after,grade,tone='warm',context={}){
 if(getLanguage()!=='it')return localComment(move,before,after,grade,tone);
 return humanComment(move,before,after,grade,tone,context);
}

export function strategicHint(c){if(getLanguage()!=='it')return localAnswer(c,'plan');if(c.isCheck())return 'Il tuo re è sotto scacco: prima risolvi questo problema.';const loose=hanging(c,c.turn());if(loose.length)return `Controlla il tuo ${piece(loose[0])}: è attaccato e non è difeso. Come puoi gestire la minaccia?`;const pin=pins(c,opposite(c.turn()))[0];if(pin)return `Il tuo ${piece(pin.pinned)} è inchiodato al re: tienine conto quando conti i difensori.`;const attacked=c.board().flat().filter(p=>p&&p.color===c.turn()&&p.type!=='k'&&c.isAttacked(p.square,opposite(c.turn())));if(attacked.length)return `Controlla attaccanti e difensori del tuo ${piece(attacked.sort((a,b)=>values[b.type]-values[a.type])[0])}.`;return c.moveNumber()<12?'Quale pezzo deve ancora entrare in gioco? Pensa anche alla sicurezza del re.':'Qual è il tuo pezzo meno attivo? Cerca un modo per migliorarlo senza trascurare le minacce.'}

export function strategyObservation(move){const c=new Chess(move.after),old=new Chess(move.before),color=move.color,centers=['d4','e4','d5','e5'];const count=pos=>centers.filter(s=>pos.isAttacked(s,color)).length,delta=count(c)-count(old);if(delta>0)return `Ora controlli ${count(c)} delle quattro case centrali, ${delta} in più di prima.`;if(delta<0)return `Dopo la mossa controlli ${count(c)} delle quattro case centrali, ${-delta} in meno di prima.`;if(move.piece==='p')return 'Hai cambiato la struttura dei pedoni: questa spinta non può essere annullata.';if(move.piece==='k')return 'Hai cambiato la posizione del re: confronta la sua attività con gli attacchi avversari.';if(move.piece==='r'){const pawns=c.board().flat().filter(p=>p?.type==='p'&&p.square[0]===move.to[0]);return pawns.length?'La torre è su una colonna che contiene ancora pedoni.':'La torre è su una colonna aperta, senza pedoni.'}return `Hai riposizionato il ${names[move.piece]}: chiediti quali compiti può svolgere nella nuova posizione.`}
export function coachAnswer(c,question,color=c.turn(),lastGrade=null){
 if(getLanguage()!=='it')return localAnswer(c,question,color,lastGrade);
 if(c.isGameOver())return c.isCheckmate()?'La partita è finita per scacco matto. Nel riepilogo puoi individuare un solo tema su cui lavorare alla prossima.':'La partita è terminata in patta. Guarda se il risultato era inevitabile oppure se avevi ancora margine prima della posizione finale.';
 if(question==='last'){if(!lastGrade?.move)return 'Appena avrai giocato una mossa, ne discuteremo qui. Per ora scegli liberamente il tuo piano.';return 'Sulla tua ultima mossa: '+briefComment(lastGrade.move,lastGrade.reviewBefore||lastGrade.before,lastGrade.after,lastGrade,'direct')}
 if(c.turn()!==color)return 'Aspettiamo la risposta dell’avversario: poi ragioniamo sulla posizione che avrai davanti.';
 if(c.isCheck())return 'Il tuo re è sotto scacco. Il primo compito è risolverlo: valuta cattura, interposizione o spostamento del re, secondo le mosse legali disponibili.';
 const pieces=c.board().flat().filter(p=>p?.color===color),enemy=opposite(color);
 if(question==='threat'){const loose=hanging(c,color);if(loose.length)return `Sono attaccati e senza difesa: ${loose.slice(0,3).map(piece).join(', ')}. Non significa che ogni cattura convenga: controlla anche eventuali compensi e ricatture.`;const attacked=pieces.filter(p=>p.type!=='k'&&c.isAttacked(p.square,enemy));return attacked.length?`Sono sotto attacco ${attacked.slice(0,3).map(piece).join(', ')}, ma hanno difensori. Conta gli scambi prima di decidere se intervenire.`:'Non vedo tuoi pezzi attaccati in questo momento. Puoi dedicarti al piano, controllando comunque le minacce che la prossima mossa avversaria potrebbe creare.'}
 if(question==='king'){const king=pieces.find(p=>p.type==='k'),file=king.square.charCodeAt(0),rank=+king.square[1];const adjacent=[];for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){const x=file+dx,y=rank+dy;if((dx||dy)&&x>=97&&x<=104&&y>=1&&y<=8){const sq=String.fromCharCode(x)+y;if(c.isAttacked(sq,enemy))adjacent.push(sq)}}return adjacent.length?`Il re non è sotto scacco, ma ${adjacent.length} case vicine sono controllate dall’avversario. Considerale quando valuti vie di fuga e difensori.`:`Il re non è sotto scacco e le case adiacenti non risultano attaccate. Non basta a garantire sicurezza: osserva anche linee aperte e possibili scacchi.`}
 if(question==='activity'&&!pieces.some(p=>'nb'.includes(p.type)))return pieces.some(p=>'rq'.includes(p.type))?'Non hai più cavalli o alfieri. Concentrati sull’attività di torri o donna, coordinandole con il re e i pedoni.':'Hai soltanto re e pedoni: conta tempi di avanzata e sostegno del re, controllando le case accessibili.';
 if(question==='activity'){const undeveloped=pieces.filter(p=>'nb'.includes(p.type)&&p.square[1]===(color==='w'?'1':'8'));if(undeveloped.length)return `Hai ancora ${undeveloped.map(piece).join(' e ')} sulla prima traversa. Quale può entrare in gioco senza perdere la difesa di qualcosa?`;return 'I pezzi leggeri non sono più sulla prima traversa. Scegli quello con meno compiti utili e valuta come migliorarlo, senza lasciare un bersaglio scoperto.'}
 const pin=pins(c,enemy)[0];if(pin)return `Prima del piano, considera il pezzo inchiodato al re: non può lasciare scoperto il re. Quali altri pezzi possono aiutarti?`;
 if(hanging(c,color).length)return 'Prima di espandere il tuo piano, c’è un pezzo attaccato e senza difesa. Decidi se proteggerlo, spostarlo o compensare il rischio: l’idea rimane tua.';
 const nonPawns=pieces.filter(p=>p.type!=='p'&&p.type!=='k');return nonPawns.length<=2?'Con pochi pezzi, attività del re e pedoni diventano centrali. Quale dei due aspetti puoi migliorare senza concedere contropiede?':'Scegli un obiettivo concreto: rendere attivo un pezzo, sostenere il centro oppure migliorare la sicurezza del re. Quale risponde meglio a ciò che vedi adesso?';
}
